        quiz:[ { q:'إلى كم صنفٍ يُقسَم الناس يوم القيامة في السورة؟', options:['ثلاثة: السابقون وأصحاب اليمين وأصحاب الشمال','صنفين'], answer:0 }, { q:'من هم خير الأصناف؟', options:['السابقون المقرّبون','أصحاب الشمال'], answer:0 }, { q:'بماذا أمر الله في آخر السورة؟', options:['تسبيح اسم ربّه العظيم','بالنوم'], answer:0 } ],
        story:[ { img:'يوم القيامة تنقسم الناس إلى ثلاثة أصناف', text:'تصف السورة يوم القيامة حين تنقسم الناس ثلاثة أصناف: السابقون المقرّبون في أعلى الجنّة، وأصحاب اليمين في نعيم، وأصحاب الشمال في عذابٍ وزقّومٍ وحميم.' }, { img:'دلائل البعث في الزرع والماء والنار', text:'تستدلّ السورة على البعث بخلق الإنسان والزرع والماء والنار، وتُعظّم القرآن الكريم، وتصوّر لحظة الموت حين تبلغ الروح الحلقوم، وتختم بأمر النبيّ ﷺ بتسبيح اسم ربّه العظيم.' }]
