        quiz:[ { q:'بِمَ أقسم الله في أول السورة؟', options:['بالقرآن المجيد','بالجبال'], answer:0 }, { q:'كم مَلَكًا يكتب أعمال الإنسان؟', options:['ملكان عن اليمين والشمال','واحد'], answer:0 }, { q:'كم قريبٌ الله من الإنسان؟', options:['أقرب من حبل الوريد','بعيد'], answer:0 } ],
