        quiz:[ { q:'كيف يجب أن نعبد الله حسب السورة؟', options:['مخلصين له الدين','بالشرك'], answer:0 }, { q:'بماذا وصف الله القرآن في السورة؟', options:['أحسن الحديث كتابًا متشابهًا مثاني','عاديًّا'], answer:0 }, { q:'ماذا قال الله للمسرفين على أنفسهم؟', options:['لا تقنطوا من رحمة الله','اقنطوا'], answer:0 } ],
