        quiz:[ { q:'بأيّ أسماء الله بدأت السورة بعد الحروف؟', options:['غافر الذنب وقابل التوب','عادية'], answer:0 }, { q:'من الذي كتم إيمانه ودافع عن موسى؟', options:['مؤمن آل فرعون','هامان'], answer:0 }, { q:'بماذا وعد الله من يدعوه؟', options:['أدعوني أستجب لكم','لا شيء'], answer:0 } ],
        story:[ { img:'مؤمنٌ من آل فرعون يكتم إيمانه ويدافع عن موسى', text:'تُسمّى سورة المؤمن، تبدأ بأسماء الله: «غافر الذنب وقابل التوب»، وتروي قصة الرجل المؤمن من آل فرعون الذي كتم إيمانه ودافع عن موسى بحكمةٍ بالغة، فوقاه الله سيّئات مكرهم.' }, { img:'باب الدعاء مفتوح: ادعوني أستجب لكم', text:'تُرسّخ السورة عظمة الدعاء: «وقال ربّكم ادعوني أستجب لكم»، وتصف الملائكة حملة العرش يستغفرون للمؤمنين، وتُحذّر من الجدال في آيات الله، وتختم بأن إيمان فرعون عند رؤية العذاب لم ينفعه.' }]
